      .start({
        account,
        secret,
        signal: controller.signal,
        state: this.state,
        onInbound: (envelope) => this.handleInbound(envelope),
        onStatus: (patch) => this.emitStatus(account, patch),
        log: (message) => this.log(`[${account.id}] ${message}`),
